import { useState } from 'react';

function App() {
  const [text, setText] = useState('');

  function handleChange(e) {
    setText(e.target.value);
  }

  return (
    <div>
      <input
        type='text'
        placeholder='kuch likho...'
        onChange={handleChange}
      />
      <h2>output:{text}</h2>
    </div>
  )
}

export default App;
